101	        {
102	            // Reparsing succeeded, but we can still fail if we're out of span
103	            // numbers to assign to nodes (this is rare).
104	            return node
105	                .replace_children(overlap, vec![reparsed])
106	                .is_ok()
107	                .then_some(new_range);
