341	    /// What kind of reparsing happened.
342	    #[derive(Debug, Clone, PartialEq, Eq)]
343	    enum Reparse<'a> {
344	        /// The whole text was reparsed.
345	        All,
346	        /// The text was parsed incrementally matching this string.
347	        Incr(&'a str),
348	    }
