350	    #[track_caller]
351	    fn test(text: &str, edit: Edit, with: &str, expected: Reparse) {
352	        let mut source = Source::detached(text);
353	        let orig_tree = source.root().clone();
354	        // `Source::edit()` is the public interface for reparsing.
355	        let replaced_range = source.edit(edit.into_range(text), with);
356	        let mut reparsed_tree = source.root().clone();
357	        let mut normal_parse = parse(source.text());
358	        reparsed_tree.synthesize(Span::detached());
359	        normal_parse.synthesize(Span::detached());
360	        if reparsed_tree != normal_parse {
361	            eprintln!("Original source text: {text:?}");
362	            eprintln!("Original tree:\n{orig_tree:#?}");
363	            eprintln!("New source text: {:?}", source.text());
364	            eprintln!("Reparsed tree:\n{reparsed_tree:#?}");
365	            eprintln!("Normal parse tree:\n{normal_parse:#?}");
366	            panic!("Reparsed tree did not match normal parse");
367	        }
368	        let actual = if replaced_range == (0..source.text().len()) {
369	            Reparse::All
370	        } else {
371	            Reparse::Incr(&source.text()[replaced_range])
